test('step: bounce off brick bottom face', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 90, r: 7, vx: 0, vy: 200 }; // moving DOWN
  state.bricks[0] = { x: 80, y: 95, w: 40, h: 20, alive: true };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'should bounce UP after hitting brick bottom');
});

test('step: bounce off brick top face', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 120, r: 7, vx: 0, vy: -200 }; // moving UP
  state.bricks[0] = { x: 80, y: 90, w: 40, h: 20, alive: true };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'should bounce DOWN after hitting brick top');
});

test('step: bounce off brick left face', () => {
  const state = createState(1);
  state.ball = { x: 130, y: 100, r: 7, vx: -200, vy: 0 }; // moving LEFT
  state.bricks[0] = { x: 80, y: 90, w: 40, h: 20, alive: true };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'should bounce RIGHT after hitting brick left');
});

test('step: bounce off brick right face', () => {
  const state = createState(1);
  state.ball = { x: 70, y: 100, r: 7, vx: 200, vy: 0 }; // moving RIGHT
  state.bricks[0] = { x: 80, y: 90, w: 40, h: 20, alive: true };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'should bounce LEFT after hitting brick right');
});

test('step: bounce off brick corner', () => {
  const state = createState(1);
  state.ball = { x: 75, y: 85, r: 7, vx: 200, vy: 200 }; // moving DOWN-RIGHT
  state.bricks[0] = { x: 80, y: 90, w: 40, h: 20, alive: true };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'should bounce UP-LEFT after hitting top-left corner');
});

test('step: push out after collision', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 100, r: 7, vx: 0, vy: 200 }; // deeply inside
  state.bricks[0] = { x: 80, y: 90, w: 40, h: 20, alive: true };
  step(state, 1 / 60);
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball should be pushed out of the brick');
});

test('step: no double bounce on neighbours', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 100, r: 7, vx: 0, vy: -200 }; // moving UP
  // Two bricks side by side, the ball hits the seam
  state.bricks[0] = { x: 80, y: 90, w: 20, h: 20, alive: true };
  state.bricks[1] = { x: 100, y: 90, w: 20, h: 20, alive: true };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'should bounce DOWN once, not twice');
});

test('step: tunnelling detection (fast ball)', () => {
  const state = createState(1);
  const speed = 2000; // very fast
  state.ball = { x: 100, y: 80, r: 7, vx: 0, vy: speed }; 
  state.bricks[0] = { x: 80, y: 100, w: 40, h: 20, alive: true };
  // In one step (1/60s), the ball moves ~33px.
  // Initial pos: 80. Next pos: 80 + 33 = 113.
  // Brick is at 100-120.
  // The ball might jump over or enter deeply, but should definitely trigger a bounce.
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'should detect collision even if ball tunnels through brick');
});

